#include "cppunivariate/distributions/ged/mle.hpp"
#include <iostream>
int main(){const double u=std::ldexp(1.,-53);std::vector<double>x{-1+u,1+2*u};const auto support=cppunivariate::ged_mle({x.data(),x.size()},1e-6,200,u,NAN,NAN);std::cout<<"support "<<int(support.status)<<" "<<support.certified<<" "<<support.stop_detail.limit_coef.size()<<" "<<support.stop_detail.candidates.size()<<"\n";if(support.status!=cppunivariate::GedStatus::TransformFailure || support.certified || !support.stop_detail.limit_coef.empty())return 1;x.clear();for(int i=1;i<=19;++i)x.push_back(i);x.push_back(1e308);const auto median=cppunivariate::ged_mle({x.data(),x.size()},1e-6,200);if(median.status!=cppunivariate::GedStatus::Nonunique || median.stop_detail.candidates.size()!=2)return 2;std::cout<<"median "<<int(median.status)<<" "<<median.stop_detail.candidates[0].coef[0]<<" "<<median.stop_detail.candidates[1].coef[0]<<" "<<median.stop_detail.candidates.size()<<"\n";return median.stop_detail.candidates[0].coef[0]!=10 || median.stop_detail.candidates[1].coef[0]!=11;}
